import {CHART_STYLES} from './chart-layouts.js';
export function initStylePicker(onChoose){const select=document.getElementById('chart-style'),picker=document.getElementById('style-picker'),trigger=document.getElementById('style-trigger');select.innerHTML=CHART_STYLES.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
 picker.innerHTML=CHART_STYLES.map(s=>`<button data-style="${s.id}" data-design-action="choose-chart" data-variant="tab" aria-pressed="false" title="${s.hint}"><strong>${s.name}</strong></button>`).join('');picker.hidden=false;
 function choose(id,remember=true){if(!CHART_STYLES.some(s=>s.id===id))id='timeline';select.value=id;trigger.textContent=CHART_STYLES.find(s=>s.id===id).name;picker.querySelectorAll('[data-style]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.style===id));const index=CHART_STYLES.findIndex(s=>s.id===id);document.getElementById('style-position').textContent=`${index+1} / ${CHART_STYLES.length}`;if(remember)try{localStorage.setItem('family-chart-style',id);}catch{}onChoose(id);}
 picker.querySelectorAll('[data-style]').forEach((b,i)=>{b.onclick=()=>choose(b.dataset.style);b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...picker.querySelectorAll('button')],next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].scrollIntoView({block:'nearest',inline:'nearest'});}});});select.onchange=()=>choose(select.value);
 let initial='timeline';try{initial=localStorage.getItem('family-chart-style')||initial;}catch{}choose(initial,false);return {choose};
}
